"""Learn matches the reference composition with one coherent set of panels."""
from html import escape


def learn(heading, icon, pearl):
    intro=heading('Connected intelligence','Understand<br>the connections.','A clear guide to agents, protocols, and recorded evidence.')
    protocols=[('a2a','A2A — Agent collaboration','A2A helps independent agents work together. Agents share goals, context and results in a structured, inspectable way.','network'),('mcp','MCP — Tools and resources','MCP gives agents a standard way to find and use tools, data and other resources, with clear context and permissions.','file'),('x402','x402 — HTTP service access','x402 is an HTTP-based payment protocol. Review the service requirements before requesting access.','link')]
    cards='<div class="grid three reference-protocol-cards">'+''.join('<article class="card"><button type="button" class="reference-protocol-button" data-learn-protocol="'+key+'" aria-controls="learn-protocol-context" aria-pressed="false"><span class="icon-disc">'+icon(glyph)+'</span><span><span class="reference-protocol-name">'+title+'</span><span class="reference-protocol-copy">'+copy+'</span><span class="reference-protocol-arrow">'+icon('arrow')+'</span></span></button></article>' for key,title,copy,glyph in protocols)+'</div>'
    topics=[('basics','Protocol basics','book'),('evidence','Reading evidence','file'),('connections','Safe connections','shield'),('patterns','Workflow patterns','network'),('glossary','Glossary','book')]
    # A tab list is not complementary content: an aside may not take role=tablist (ARIA in HTML).
    sidebar='<div class="side-nav card" role="tablist" aria-label="Learning topics" aria-orientation="vertical">'+''.join('<button type="button" class="side-item'+(' active'if index==0 else '')+'" id="learn-tab-'+key+'" role="tab" data-learn-tab="'+key+'" aria-controls="learn-panel-'+key+'" aria-selected="'+('true'if index==0 else'false')+'" tabindex="'+('0'if index==0 else'-1')+'">'+icon(glyph)+'<span>'+label+'</span>'+icon('chevron')+'</button>' for index,(key,label,glyph) in enumerate(topics))+'</div>'
    previews=['<div class="reference-task-preview">'+icon('file')+'<span>Task description<i></i><i></i></span></div>','<div class="reference-source-preview">'+''.join('<p>'+icon('file')+label+icon('chevron')+'</p>'for label in ['Agent output','Source document','Tool usage record'])+'</div>','<div class="reference-connection-preview">'+''.join('<span>'+icon(glyph)+'<small>'+label+'</small></span>'+(' → 'if index<2 else'')for index,(label,glyph)in enumerate([('Agent','network'),('Tool','settings'),('Service','file')]))+'</div>']
    steps=[('Start with a task','Define what you want to accomplish. Identify the type of agent that can help, and what additional tools or information may be needed.'),('Inspect the evidence','Review the agent’s outputs, supporting documents and tool usage. Look for clear, traceable evidence for each step.'),('Review each connection','Understand how agents, tools and services are linked. Check the purpose, inputs and outputs at each step before you run or reuse a workflow.')]
    basics='<h2>From one agent to a connected workflow.</h2><p class="reference-learn-lead">Each agent has individual strengths. The real value comes from connecting the right agents, tools and services to accomplish a broader goal.</p><section id="learn-protocol-context" class="learn-protocol-context" aria-live="polite" hidden></section>'+''.join('<section class="reference-learn-step"><span class="reference-step-number">'+str(index+1)+'</span><div><h3>'+title+'</h3><p>'+copy+'</p></div><div class="reference-learn-example"><span class="caption">Example preview</span>'+previews[index]+'</div></section>' for index,(title,copy)in enumerate(steps))
    evidence='<h2>Read the evidence. Understand its scope.</h2><p class="reference-learn-lead">A report and an execution check answer different questions. Inspect the input, output, sources and date before deciding what to use.</p><div class="learn-topic-grid"><article><span class="icon-disc">'+icon('file')+'</span><h3>Recorded reports</h3><p>A saved account of a previous result. Read the request, returned content and supporting sources.</p></article><article><span class="icon-disc">'+icon('activity')+'</span><h3>Execution checks</h3><p>An observation of a particular connection and request at a recorded time. Availability can change.</p></article></div><h3>Before you rely on a result</h3><ul><li>Check which agent and protocol were used.</li><li>Compare the recorded input with your intended task.</li><li>Review source links, timestamps and limitations.</li><li>Keep past observations separate from current availability.</li></ul>'
    connections='<h2>Make each connection a considered choice.</h2><p class="reference-learn-lead">Understand the selected agent, the information it will receive and the result you expect before running a request.</p><div class="learn-topic-grid"><article><span class="icon-disc">'+icon('shield')+'</span><h3>Review the destination</h3><p>Inspect the public agent details, supported protocol and intended task.</p></article><article><span class="icon-disc">'+icon('user')+'</span><h3>Share with purpose</h3><p>Include only the input needed for the task. Keep credentials and unnecessary personal information out of requests.</p></article></div><h3>Keep control of the next step</h3><p>Review inputs before each run. Task updates are optional and require separate authorization and destination verification.</p>'
    patterns='<h2>Individual strengths. One useful outcome.</h2><p class="reference-learn-lead">A workflow connects selected capabilities in a sequence you can inspect.</p><div class="learn-pattern-strand">'+''.join('<article>'+pearl('large')+'<h3>'+title+'</h3><p>'+copy+'</p></article>'for title,copy in [('Discover','Find an agent relevant to the task.'),('Review','Inspect capabilities, evidence and shared inputs.'),('Connect','Run the reviewed steps and inspect the result.')])+'</div><h3>Follow the information between steps</h3><p>Check what each step receives and returns. Review the selected connections and the current workflow input before execution.</p><a class="btn primary" href="workflows.html">Review workflows '+icon('arrow')+'</a>'
    glossary='<h2>A shared language for useful connections.</h2><p class="reference-learn-lead">Start with these terms as you explore agents and inspect their evidence.</p><dl class="learn-glossary">'+''.join('<div><dt>'+term+'</dt><dd>'+copy+'</dd></div>'for term,copy in [('Agent','A service that offers capabilities for a task.'),('Protocol','The supported way to communicate with an agent, tool or service.'),('Tool','A capability that can be used with defined inputs.'),('Recorded report','A saved account of a previous result and its evidence.'),('Execution check','A recorded observation of a specific request and connection.'),('Workflow','A sequence of connected capabilities, inputs and results.')])+'</dl>'
    contents={'basics':basics,'evidence':evidence,'connections':connections,'patterns':patterns,'glossary':glossary}
    panels='<article class="card reference-learn-panels">'+''.join('<section id="learn-panel-'+key+'" role="tabpanel" aria-labelledby="learn-tab-'+key+'" tabindex="0"'+(' hidden'if key!='basics'else'')+'>'+contents[key]+'</section>'for key,_,_ in topics)+'</article>'
    layout='<section class="workflow-layout reference-learn-body">'+sidebar+panels+'</section>'
    disclosure='<section class="card reference-learn-evidence"><span class="icon-disc">'+icon('file')+'</span><div><h3>Reports and execution checks are different.</h3><p>Recorded reports are a history of what happened. Execution checks show what an agent, tool or service returned at a specific time, and may change with new inputs or conditions. Use both to understand results.</p></div><div><h4>Recorded reports</h4><p>A saved history of outputs, documents and key steps.</p></div><div><h4>Execution checks</h4><p>A time-dependent view of what an agent, tool or service returned.</p></div></section>'
    next_steps=[('Explore agents','Find capable agents for your tasks.','search','explore.html'),('Try a test','Run a reviewed example.','play','test.html'),('Review workflows','See agents working together.','network','workflows.html')]
    actions='<section class="reference-learn-next"><div class="between"><h2>Choose your next step.</h2><p>Explore agents, try a simple test, or review supported workflows to see how everything fits together.</p></div><div class="grid three">'+''.join('<a class="card" href="'+href+'"><span class="icon-disc">'+icon(glyph)+'</span><span><h3>'+title+'</h3><p>'+copy+'</p></span>'+icon('arrow')+'</a>'for title,copy,glyph,href in next_steps)+'</div></section>'
    faq='<section class="reference-learn-faq"><h2>Frequently asked questions.</h2><div><details><summary>How do I choose the right protocol for my use case?</summary><p>Start with the task, inspect the agent’s public connection details, and choose a supported protocol.</p></details><details><summary>How do I read execution checks and supporting evidence?</summary><p>Inspect the recorded input, result, sources and timestamp. Past evidence does not guarantee current availability.</p></details></div></section>'
    return intro+cards+layout+disclosure+actions+faq
